    // DEMOCRACY RECOVERY (Tier 2): Added recovery mechanisms
    // emergencyManagement is always initialized with activeResponses array
    const emergencyManagement = assertStateProperty(state, 'emergencyManagement', {
      location: 'DemocracyDynamicsPhase.execute',
      month: state.currentMonth
    });
    const activeResponses = assertStateProperty(emergencyManagement, 'activeResponses', {
